# Let's try to infer the transformation rule
# Try: output[r][c] = input[something][something]

def try_solve():
    # For each output cell, find which input cell it comes from
    mapping = {}
    for r in range(8):
        for c in range(8):
            if output[r][c] in [3, 5]:
                pass

    # Let's look at patterns for each quadrant
    # TL: 2x scaled, so output[r][c] for r,c<4 = input[r//2][c//2]?
    # Let me test this
    for r in range(4):
        for c in range(4):
            scaled = input[r//2][c//2]
            if output[r][c] != scaled:
                print(f"TL mismatch: output[{r}][{c}]={output[r][c]} but input[{r}//2][{c}//2]={scaled}")
                break
        else:
            continue
        break
    else:
        print("TL matches 2x scaling: output[r][c] = input[r//2][c//2] for r,c in 0:4")

    # BR: let's see if it's original input
    for r in range(4):
        for c in range(4):
            if output[r+4][c+4] != input[r][c]:
                print(f"BR mismatch: output[{r+4}][{c+4}]={output[r+4][c+4]} but input[{r}][{c}]={input[r][c]}")
                break
        else:
            continue
        break
    else:
        print("BR matches original input: output[r+4][c+4] = input[r][c]")

try_solve()

# Now TR
print("\nQuadrant TR (rows 0-3, cols 4-7):")
tr_quad = [[output[r][c] for c in range(4,8)] for r in range(4)]
print(tr_quad)

# Check if TR is input rotated 90 degrees one way or another
print("\nTrying TR = input rotated 90 CCW:")
rot90ccw = [[input[3-c][r] for c in range(4)] for r in range(4)]
for r in range(4):
    for c in range(4):
        if tr_quad[r][c] != rot90ccw[r][c]:
            print(f"Mismatch at [{r}][{c}]: TR={tr_quad[r][c]}, rot90ccw={rot90ccw[r][c]}")

print("\nTrying TR = input rotated 90 CW:")
rot90cw = [[input[r][3-c] for c in range(4)] for r in range(4)]
for r in range(4):
    for c in range(4):
        if tr_quad[r][c] != rot90cw[r][c]:
            print(f"Mismatch at [{r}][{c}]: TR={tr_quad[r][c]}, rot90cw={rot90cw[r][c]}")

# Check BL
print("\nQuadrant BL (rows 4-7, cols 0-3):")
bl_quad = [[output[r][c] for c in range(4)] for r in range(4,8)]
print(bl_quad)

print("\nTrying BL = input rotated 90 CCW:")
for r in range(4):
    for c in range(4):
        if bl_quad[r][c] != rot90ccw[r][c]:
            print(f"Mismatch at [{r}][{c}]: BL={bl_quad[r][c]}, rot90ccw={rot90ccw[r][c]}")
            break
    else:
        continue
    break
else:
    print("BL matches rot90ccw!")

# Build the output based on the derived pattern
test_input = [[6, 6], [6, 1]]
n = 2  # input size

# Output starts as 2*n x 2*n grid
output = [[0] * (2*n) for _ in range(2*n)]

# TL: original input
for r in range(n):
    for c in range(n):
        output[r][c] = test_input[r][c]

# TR: diagonal[r] repeated for each row
for r in range(n):
    diag_val = test_input[r][r]
    for c in range(n, 2*n):
        output[r][c] = diag_val

# BL: diagonal repeated for each row
for r in range(n, 2*n):
    for c in range(n):
        output[r][c] = test_input[c][c]  # column c of diagonal

# BR: original input
for r in range(n, 2*n):
    for c in range(n, 2*n):
        output[r][c] = test_input[r-n][c-n]

print("Output:")
for row in output:
